import React, { useMemo, useCallback } from "react"
import _ from "lodash"
import styled from "styled-components"

const RelativeWrapper = styled.div`
  position: relative;
`

const Wrapper = styled.aside`
  position: absolute;
  left: 112%;
  top: 0px;
  width: 240px;
  font-size: 16px;

  @media (max-width: 1300px) {
    display: none;
  }
`

const Title = styled.div`
  margin-bottom: 20px;
  font-weight: 700;
  font-size: 18px;
  color: ${props => props.theme?.colors?.text || '#333'};
  background: linear-gradient(135deg, ${props => props.theme?.colors?.onseokBlue || '#2563eb'} 0%, ${props => props.theme?.colors?.onseokPurple || '#7c3aed'} 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  text-transform: uppercase;
  letter-spacing: 0.5px;
`

const StatusIndicator = styled.div`
  margin-bottom: 16px;
  padding: 8px 12px;
  background: ${props => props.theme?.colors?.hoveredLinkBackground || '#f0f0f0'};
  border-radius: 8px;
  font-size: 13px;
  font-weight: 500;
  color: ${props => props.theme?.colors?.secondaryText || '#666'};
  text-align: center;
`

const TagList = styled.ul`
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
`

const Tag = styled.li`
  position: relative;
  padding: 10px 16px;
  color: ${props => props.selected 
    ? '#fff'
    : props.theme?.colors?.tertiaryText || '#999'
  };
  background: ${props => props.selected 
    ? `linear-gradient(135deg, ${props.theme?.colors?.onseokBlue || '#2563eb'} 0%, ${props.theme?.colors?.onseokPurple || '#7c3aed'} 100%)`
    : 'transparent'
  };
  border: 2px solid ${props => props.selected 
    ? 'transparent'
    : props.theme?.colors?.hoveredLinkBackground || '#e5e7eb'
  };
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  font-weight: ${props => props.selected ? '600' : '500'};
  font-size: 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  overflow: hidden;

  &:before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(135deg, ${props => props.theme?.colors?.onseokBlue || '#2563eb'} 0%, ${props => props.theme?.colors?.onseokPurple || '#7c3aed'} 100%);
    opacity: 0;
    transition: opacity 0.3s ease;
    z-index: -1;
  }

  &:hover {
    color: ${props => props.selected ? '#fff' : props.theme?.colors?.text || '#333'};
    border-color: ${props => props.selected ? 'transparent' : props.theme?.colors?.onseokBlue || '#2563eb'};
    transform: ${props => props.selected ? 'translateY(-2px)' : 'translateY(-1px)'};
    box-shadow: ${props => props.selected 
      ? '0 8px 25px -5px rgba(37, 99, 235, 0.3)'
      : '0 4px 12px -2px rgba(0, 0, 0, 0.1)'
    };

    &:before {
      opacity: ${props => props.selected ? '1' : '0.05'};
    }
  }

  &:active {
    transform: translateY(0);
  }
`

const TagName = styled.span`
  position: relative;
  z-index: 1;
  font-weight: inherit;
`

const TagCount = styled.span`
  position: relative;
  z-index: 1;
  font-size: 12px;
  font-weight: 600;
  opacity: 0.8;
  background: ${props => props.selected 
    ? 'rgba(255, 255, 255, 0.2)'
    : props.theme?.colors?.hoveredLinkBackground || '#f0f0f0'
  };
  padding: 2px 8px;
  border-radius: 12px;
  min-width: 20px;
  text-align: center;
`

const SideTagList = React.memo(({ tagList, selectedTag, onClick }) => {
  const totalPosts = useMemo(() => {
    return tagList ? tagList.reduce((sum, tag) => sum + tag.totalCount, 0) : 0
  }, [tagList])
  
  const handleTagClick = useCallback((tagValue) => {
    onClick(tagValue)
  }, [onClick])

  const statusText = useMemo(() => {
    if (selectedTag) {
      const selectedTagData = tagList?.find(tag => tag.fieldValue === selectedTag)
      return `${selectedTagData?.totalCount || 0}개의 포스트 표시 중`
    }
    return `전체 ${totalPosts}개의 포스트`
  }, [selectedTag, tagList, totalPosts])
  
  return (
    <RelativeWrapper>
      <Wrapper>
        <Title>태그 목록</Title>
        <StatusIndicator>
          {statusText}
        </StatusIndicator>
        <TagList>
          {tagList && tagList.map(tag => (
            <Tag 
              key={tag.fieldValue}
              selected={selectedTag === tag.fieldValue}
              onClick={() => handleTagClick(tag.fieldValue)}
            >
              <TagName>#{tag.fieldValue}</TagName>
              <TagCount selected={selectedTag === tag.fieldValue}>
                {tag.totalCount}
              </TagCount>
            </Tag>
          ))}
        </TagList>
      </Wrapper>
    </RelativeWrapper>
  )
})

export default SideTagList
