import React, { useState, useEffect, useMemo, useCallback } from "react"
import { graphql } from "gatsby"
import _ from "lodash"

import Layout from "components/Layout"
import SEO from "components/SEO"
import Bio from "components/Bio"
import PostList from "components/PostList"
import SideTagList from "components/SideTagList"
import VerticalSpace from "components/VerticalSpace"
import { filterPostsByTag } from "utils/postUtils"

const IndexPage = React.memo(({ data }) => {
  const posts = data.allMarkdownRemark.nodes
  const tags = data.allMarkdownRemark.group
  const aboutData = data.aboutMarkdownRemark

  const [selectedTag, setSelectedTag] = useState(null)

  // 필터링된 포스트 계산 메모이제이션
  const filteredPosts = useMemo(() => {
    return filterPostsByTag(posts, selectedTag)
  }, [posts, selectedTag])

  const handleClickTag = useCallback(tag => {
    if (selectedTag === tag) {
      setSelectedTag(null)
    } else {
      setSelectedTag(tag)
    }
  }, [selectedTag])

  return (
    <Layout>
      <SEO title="Home" />
      <VerticalSpace size={48} />
      <Bio aboutData={aboutData} />
      <SideTagList
        tagList={tags}
        selectedTag={selectedTag}
        onClick={handleClickTag}
      />
      <PostList postList={filteredPosts} />
    </Layout>
  )
})

export default IndexPage

export const pageQuery = graphql`
  query {
    site {
      siteMetadata {
        title
      }
    }
    aboutMarkdownRemark: markdownRemark(
      fileAbsolutePath: { regex: "/contents/about/" }
    ) {
      html
      frontmatter {
        title
      }
    }
    allMarkdownRemark(
      sort: { frontmatter: { date: DESC } }
      filter: { fileAbsolutePath: { regex: "/contents/posts/" } }
    ) {
      group(field: { frontmatter: { tags: SELECT } }) {
        fieldValue
        totalCount
      }
      nodes {
        excerpt(pruneLength: 200, truncate: true)
        html
        fields {
          slug
          readingTime {
            minutes
          }
        }
        frontmatter {
          date
          update
          title
          tags
          thumbnail {
            publicURL
          }
        }
      }
    }
  }
`
